insert into public.cms_documents(module,slug,draft) values('pages','home','{"title":"ホーム","fields":{"home.text_a124ef90":"STAGE PARTNERSが向き合う土地と建物","home.text_579bb17d":"REAL ESTATE &amp; ARCHITECTURE","home.text_d73b6a3f":"挑戦する人が、","home.text_fc0100c0":"輝ける場所を。","home.text_6bd321c2":"不動産の仲介・管理から、建物のリフォーム・改修まで。","home.text_fef657d4":"静岡・東京・神奈川を拠点に、オーナー様の資産の可能性を、一貫して引き出します。","home.text_c4559d6d":"無料で相談する","home.text_bb3e382c":"SCROLL","home.text_2f94f737":"不動産や建築を扱うということは、主役は私たちではない。","home.text_fa70ef79":"主役は、","home.text_b3d0fd30":"その場所で挑戦する人たちだ。","home.text_b769730f":"私たちは、その人たちが輝くための舞台を創る。","home.text_1655e5b6":"メッセージ","home.text_37819144":"MESSAGE","home.text_9323d95d":"私たちについて","home.text_9ff16c01":"空室が埋まらない","home.text_95c07976":"募集しても入居が決まらない、稼働率が上がらない。収益の土台が揺らいでいる。","home.text_22e7d05a":"建物の老朽化","home.text_4316e014":"外観や設備の傷みが目立ってきた。どこから、どこまで手を入れるべきか判断がつかない。","home.text_fc674e4f":"管理の負担","home.text_642d8522":"入居者対応や日々の管理に手が回らない。任せられる相手が近くにいない。","home.text_14b80d87":"改修費用が読めない","home.text_872da953":"リフォームすべきかどうか、いくらかかり、いくら戻るのか。費用対効果が見えない。","home.text_ff232e9":"資産の活かし方","home.text_e4676144":"貸すべきか、売るべきか、直して活かすべきか。土地と建物の次の一手に迷っている。","home.text_e361272b":"YOUR CONCERNS","home.text_3469f263":"その土地と建物の悩み、","home.text_982fedeb":"抱え込んでいませんか。","home.text_b14ae90c":"オーナー様が直面しやすい課題を、STAGE PARTNERSは不動産と建築の両面から解きほぐします。","home.text_d04dc443":"CONTACT","home.text_2b7d32d1":"まずは、","home.text_49a85e3e":"話を聞いてほしい。","home.text_5e621c1":"不動産ソリューション","home.text_30468aee":"仲介・管理・買取再販","home.text_3c8ff9b":"オーナー様の「貸したい・売りたい」に応え、\n確かな価値へとつなぎます。","home.text_837c9db1":"借主・買主をお探しする仲介。媒介契約を結び、募集を開始します。","home.text_88b2d675":"オーナー様と入居者の間に立つ管理。契約・入居中の対応・原状回復まで。","home.text_37d5a3a0":"当社で買い取り、価値を高めて次の所有者へお渡しする買取・再販。","home.text_c8c44591":"建築ソリューション","home.text_9f014c0":"新規出店・リノベーション","home.text_d2aae866":"店舗・オフィスの新規出店から、空室・老朽化への対応まで。\nデザインから施工まで一社で担います。","home.text_13cb6feb":"店舗・オフィス等の新規出店を、デザインから施工まで一貫対応","home.text_95a327f5":"空室対策・原状回復から本格的なリノベーションまで","home.text_231b05c5":"自社で不動産まで見通すからこそ描ける、活かす前提の設計","home.text_f4a6dce5":"OUR SOLUTIONS","home.text_cc016a58":"不動産と建築を、","home.text_807539a0":"一社でつなぐ。","home.text_1e2b7cf1":"仲介で終わらせず、リフォームで価値を高め、管理まで。","home.text_2d80074f":"事業を分けずに一気通貫で担うからこそ、土地と建物の可能性を最大限に引き出せます。","home.text_4293882a":"詳細を見る","home.text_f1572d2e":"不動産と建築の一体対応","home.text_4e61863f":"仲介・買取から改修、そして管理まで。窓口を分けずに一社で担うから、判断も対応も速い。","home.text_b45bf55e":"幅広い施工力","home.text_e7322d58":"小さな原状回復から一棟のリノベーションまで。住まいにも収益物件にも柔軟に応えます。","home.text_26c2a0aa":"買って終わりにしない","home.text_9c2b3956":"売買や改修の後も、維持管理で長く伴走。資産の価値を、その先まで守り続けます。","home.text_b637cd77":"OUR STRENGTHS","home.text_e26834a3":"選ばれる、","home.text_28e47dc5":"3つの理由。","home.text_2a333f37":"不動産と建築、その両方を知る会社だからこそ提供できる価値があります。","home.text_45416a3":"土地と建物のこと、","home.text_53b12b90":"まずは聞かせてください。","home.text_cbbef164":"売却・賃貸・リフォーム・管理まで、","home.text_a78ef19d":"どんな段階のご相談でも構いません。","home.text_13e14d85":"ご相談は無料です。お気軽にお問い合わせください。","home.text_f68d90b6":"お問い合わせフォームへ","home.text_413d0f9a":"TEL","home.link_text_1fcf056e":"/contact","home.link_text_c2028085":"/company","home.link_text_982f41a4":"/business/real-estate","home.link_text_e942455e":"/business/architecture"}}'::jsonb);
insert into public.cms_published(document_id,module,slug,data,version,source) select id,module,slug,draft,version,source from public.cms_documents where module='pages' and slug='home';
insert into public.cms_revisions(document_id,version,action,data) select id,version,'baseline.import',draft from public.cms_documents where module='pages' and slug='home';
insert into public.cms_documents(module,slug,draft) values('pages','real-estate','{"title":"不動産ソリューション","fields":{"real-estate.text_89aa44a6":"取り扱い業務","real-estate.text_71a3876d":"オーナー様へ","real-estate.text_36091759":"ご相談の流れ","real-estate.text_466ab818":"物件をお探しの方","real-estate.text_e53f7505":"売買・賃貸の仲介","real-estate.text_2e6dc5c0":"土地・建物の売買、テナントや住まいの賃貸を仲介します。売りたい・貸したいというオーナー様のご要望と、借りたい・買いたいという方のご希望の間に立ち、条件をすり合わせて成約まで進めます。","real-estate.text_f98f63d1":"賃貸管理","real-estate.text_87272156":"入居者の募集から契約、入居中の対応、退去時の原状回復まで引き受けます。建築部門を自社に持っているため、修繕が必要になったときも外注を挟まずそのまま動けます。","real-estate.text_c2d84c37":"買取・再販","real-estate.text_56a89ae2":"土地や建物を当社で買い取り、リフォームで手を入れてから次の所有者へお渡しします。相続や住み替えで早く手放したい場合も、買主を探す期間を待たずに進められます。","real-estate.text_9ff16c01":"空室が埋まらない","real-estate.text_dc0062e3":"募集条件の見直しだけで解決しないときは、建築部門と一緒に原因を見ます。設備の古さが理由なら、費用対効果を見たうえで改修をご提案します。","real-estate.text_d024f2a0":"建物が古くなってきた","real-estate.text_9b8316aa":"現状のまま貸し続けるか、手を入れて賃料を上げるか、売却するか。それぞれの収支を並べてお出しし、そのうえで方針を決めていただきます。","real-estate.text_c54474ad":"相続した土地の使い道が決まらない","real-estate.text_c1f8a7ea":"そのまま売る、貸す、建てて貸す。立地と法規制から現実的な選択肢を絞り、判断に必要な数字をそろえます。","real-estate.text_328e7a52":"ご相談","real-estate.text_426f9876":"お電話・お問い合わせフォームからご連絡ください。所在地と現在の状況を伺います。この時点で費用はかかりません。","real-estate.text_1667bd55":"現地確認・調査","real-estate.text_be981adb":"物件を実際に拝見し、法規制や周辺の相場を調べます。建物がある場合は、劣化の状況もあわせて確認します。","real-estate.text_cf0938f3":"ご提案","real-estate.text_dda1d7b3":"売る・貸す・手を入れて活かす。とりうる選択肢を、それぞれの想定収支と期間とともにお示しします。","real-estate.text_e4c14fca":"契約・募集開始","real-estate.text_af3cb111":"方針が決まりましたら、媒介契約を結び、募集を開始します。進捗は定期的にご報告します。","real-estate.text_7faf6168":"成約・引き渡し","real-estate.text_702c65e3":"条件が整いましたら契約手続きに進みます。管理をお任せいただく場合は、ここから入居中の対応が始まります。","real-estate.text_f939097b":"REAL ESTATE SOLUTIONS","real-estate.text_5e621c1":"不動産ソリューション","real-estate.text_8b2acc31":"売買・賃貸の仲介から管理、買取・再販まで。建築部門を自社に持つ強みを活かし、","real-estate.text_f2cf8fae":"貸す・売る・活かすの判断からその先の手入れまでを一社でお引き受けします。","real-estate.text_a81b9982":"このページの内容","real-estate.text_d90c0344":"SERVICE","real-estate.text_d8030973":"住まいから事業用の物件まで、不動産に関わる業務を一通り扱います。","real-estate.text_28513531":"仲介して終わりではなく、貸した後の管理や、必要になったときの改修まで見据えてご提案します。","real-estate.text_e74be6ec":"FOR OWNERS","real-estate.text_9e68b181":"土地や建物をお持ちの方から特に多くいただくご相談は、次の三つです。いずれも「不動産だけ」「建築だけ」では答えが出ません。私たちは両方を自社で持っているため、貸し方の見直しと建物への手入れを同じテーブルで検討できます。","real-estate.text_c2d16e23":"沼津の街並みと建ち並ぶ住宅","real-estate.text_fbb9af55":"FLOW","real-estate.text_af0b5713":"ご相談から成約まで、五つの段階を踏みます。現地確認とご提案までは費用をいただきません。方針が決まらないうちに契約を迫ることもありません。","real-estate.text_e3111664":"PROPERTY SEARCH","real-estate.text_39b4af20":"物件をお探しの方へ","real-estate.text_63de8333":"現在お取り扱い中の物件は、不動産情報サイト「at home」に掲載しています。間取りや写真、周辺環境まで掲載していますので、まずはこちらをご覧ください。","real-estate.text_3140fbbd":"掲載されていない物件のご相談や、条件を決めてお探しすることも承ります。ご希望がお決まりでない段階でも構いませんので、お気軽にお問い合わせください。","real-estate.text_3b94750a":"at homeで掲載物件を見る","real-estate.text_a553baf1":"外部サイト（at home）が新しいタブで開きます","real-estate.text_e182966b":"貸すか、売るか、手を入れて活かすか。","real-estate.text_21d55ea5":"判断の材料からご一緒します。","real-estate.text_6eda855c":"お問い合わせ","real-estate.text_d468a407":"建築ソリューションを見る","real-estate.link_text_d3d8fd0d":"https://www.athome.co.jp/ahcb/aim.html","real-estate.link_text_1fcf056e":"/contact","real-estate.link_text_e942455e":"/business/architecture","real-estate.text_d8f46eba":"不動産ソリューション | STAGE PARTNERS","real-estate.text_f79c2d80":"STAGE PARTNERSの不動産ソリューションについて。売買・賃貸の仲介から賃貸管理、買取・再販まで。建築部門を自社に持つ強みを活かし、貸す・売る・活かすの判断からその先の手入れまでお引き受けします。"}}'::jsonb);
insert into public.cms_published(document_id,module,slug,data,version,source) select id,module,slug,draft,version,source from public.cms_documents where module='pages' and slug='real-estate';
insert into public.cms_revisions(document_id,version,action,data) select id,version,'baseline.import',draft from public.cms_documents where module='pages' and slug='real-estate';
insert into public.cms_documents(module,slug,draft) values('pages','architecture','{"title":"建築ソリューション","fields":{"architecture.text_e83d828":"オフィス","architecture.text_dd97fdcb":"飲食店","architecture.text_b98c1c54":"美容室","architecture.text_837efa17":"クリニック","architecture.text_90d00915":"スポーツ施設","architecture.text_d8eb82e7":"居酒屋","architecture.text_31595b9e":"携帯ショップ","architecture.text_e3d2c4e9":"遊技場","architecture.text_876a84fb":"対応する工事","architecture.text_3d7fce61":"店舗設計・施工","architecture.text_4edf58fa":"施設営繕","architecture.text_1c623e04":"空きテナントのご相談","architecture.text_a6b95e":"ヒアリング","architecture.text_f54c36f1":"お店のコンセプトと、譲れない条件を伺います。予算と開店希望日も、この時点で共有してください。","architecture.text_93cdae40":"プランニング","architecture.text_42cf4e5b":"間取りを図面に落とし、パースで完成形をご覧いただきます。ここで大きな方向を決めます。","architecture.text_e4a35d17":"デザイン制作","architecture.text_b17b923a":"設備と什器の位置、寸法を確定します。レイアウトが決まると、働きやすさもほぼ決まります。","architecture.text_a3580742":"詳細設計・お見積もり","architecture.text_467efcd1":"色や質感、家具、必要な設備を一つずつ決めます。\n費用と工期をお示しし、ご了承をいただいてから着工日を確定します。","architecture.text_a9bf8f77":"施工","architecture.text_4cbd9c8c":"解体、造作、仕上げの順に進みます。工事中は定期的に進捗をご報告し、\n変更が必要になればその都度ご相談します。","architecture.text_6b553a71":"引き渡し・検査","architecture.text_ccc60bbf":"設備の使い方をご説明し、検査を受けます。保健所や消防署の営業許可も、ここで取得します。\n引き渡した後の不具合にも対応します。","architecture.text_f4c507f8":"点検","architecture.text_438c03cb":"建築基準法と官公法で定められた点検です。建物と敷地、昇降機、建築設備、防火設備の劣化を確認します。","architecture.text_912e97ef":"補修","architecture.text_d19735da":"決まった周期ではなく、不具合が出た箇所に対して行います。実用上の問題がない状態まで戻します。","architecture.text_1726ad9d":"メンテナンス","architecture.text_7eee0f5c":"日々の清掃、設備の点検、リニューアル工事。空調が効いて水が出る、その当たり前を保ちます。","architecture.text_9ea1ac4a":"ARCHITECTURE SOLUTIONS","architecture.text_c8c44591":"建築ソリューション","architecture.text_fd10d3b5":"店舗・オフィス等の新規出店から、住まいの改修、建てた後の維持管理まで。図面を引くところから引き渡した先まで、一社で受けます。","architecture.text_a81b9982":"このページの内容","architecture.text_a17dd30b":"SCOPE","architecture.text_43e8b769":"店舗・オフィス等の新規出店は、デザインから施工まで一貫してお引き受けします。壁紙の張り替えやエアコンの交換といった一日で終わる工事から、フロアをまるごと変える大型リニューアルまで扱います。業種が変われば必要な設備も動線も変わるので、図面はいつも一から引き直します。","architecture.text_3a777a03":"住まいも同じです。二世帯住宅への間取り変更、マンションのリノベーション。家族の人数が変われば、必要な部屋の数も位置も変わります。","architecture.text_28d08777":"INDUSTRIES","architecture.text_2c8b195c":"STORE DESIGN","architecture.text_1efa6596":"私たちは、店舗デザインのプロフェッショナルとして、お客様のブランドやアイデンティティを反映させながら、魅力的で機能的な空間を創り出します。内装工事では高品質な施工を心がけ、営繕管理では施設を持続可能な状態に保ちます。そして、新しい店舗をお探しの方には、適切な空き店舗の提案も行います。","architecture.text_3756cc20":"テナント施設を紹介し、作り、守ることで、店舗設計における三拍子が揃ったスペシャリストとして、お客様のビジネス成功に向けて全力でサポートします。私たちは、お客様とともに成長し、繁栄する未来を築くために、真摯かつ専門的なサービスを提供いたします。","architecture.text_463504dd":"店舗ができるまで","architecture.text_8e4be6cd":"ご相談から引き渡しまで、六つの段階を踏みます。","architecture.text_ee6bbc5a":"どの段階でも図面と見積もりをご覧いただき、合意してから次へ進みます。","architecture.text_be50439e":"建物の劣化状況を点検する現場担当者","architecture.text_9b714d20":"MAINTENANCE","architecture.text_92312a4c":"施設はお客様の重要な財産です。その価値を守るために、定期的な点検、必要な補修、継続的なメンテナンスを実施いたします。私たちは、高い専門性と信頼性をもって、お客様の施設を確実に管理し、持続可能な状態を維持します。","architecture.text_bb8e3f66":"施設営繕の内容","architecture.text_3958b9e1":"VACANCY SUPPORT","architecture.text_fad6e42e":"空きテナントでお困りのオーナー様へ","architecture.text_5ba99b61":"空き店舗の修繕や改修により、ビルの価値を高め、魅力的な賃貸スペースに変貌させることが可能です。私たちは、これらのプロセスに関する豊富な経験と専門知識を持ち、改修後は不動産事業のノウハウを活かして事業者の募集をサポートします。特に、借り手が集まらないビルのオーナー様にとって、このサービスは大きな助けとなります。","architecture.text_f8b24beb":"私たちは、ビルの魅力を引き出し、適切なテナントの選定や効果的なマーケティング戦略を提供します。空きスペースの有効活用はオーナー様の収益向上に直結し、私たちはそのお手伝いを致します。空き店舗にお困りのビルオーナー様は、ぜひお気軽にご相談ください。専門的なチームが全力でサポートし、ビジネスの成功をサポートいたします。","architecture.text_d6d5f77":"不動産ソリューションを見る","architecture.text_affa875d":"クライアントの課題解決","architecture.text_7f0fc056":"仕上がりは、実際の現場でご覧ください。","architecture.text_c0205f4e":"施工実績を見る","architecture.text_db03c80e":"工事の規模や費用の目安については、","architecture.text_6eda855c":"お問い合わせ","architecture.text_1d4bfb76":"からご相談ください。","architecture.link_text_982f41a4":"/business/real-estate","architecture.link_text_e3937a50":"/works","architecture.link_text_1fcf056e":"/contact","architecture.text_5f034d0b":"建築ソリューション｜店舗の内装工事・リノベーション・施設営繕 | STAGE PARTNERS","architecture.text_3e5d1531":"飲食店・美容室・クリニックなどの店舗デザイン施工から、住まいのリノベーション、建物の点検・補修・メンテナンスまで。静岡県沼津市のSTAGE PARTNERSが、設計から引き渡し後の維持管理まで一社で担います。空き店舗の改修とテナント募集もご相談ください。"}}'::jsonb);
