insert into public.cms_documents(module,slug,draft) values('pages','company','{"title":"会社概要","fields":{"company.text_cac0b0c":"会社名","company.text_798ce0af":"本社","company.text_6a49f7db":"事業内容","company.text_5309633c":"不動産ソリューション（仲介・管理・買取再販）／ 建築ソリューション（新規出店・リノベーション・営繕）","company.text_b935f4c4":"許認可","company.text_7d769c70":"宅地建物取引業免許　静岡県知事(1)第15176号","company.text_13c761f9":"一般建設業登録　静岡県知事許可(般-6)第39891号","company.text_4ab4353":"一級建築士事務所　","company.text_63f2cdff":"STAGE PARTNERSの拠点と街並み","company.text_784b295c":"COMPANY","company.text_828b9630":"会社概要","company.text_2d1e7942":"（外部サイト・新しいタブで開きます）","company.link_text_75cdcfb4":"https://www.sunpla-hd.co.jp/","company.link_text_b7a72c63":"https://www.sunpla.info/","company.link_text_a8640cf1":"https://www.soleil-fuji.co.jp/","company.link_text_3a4b6a9e":"https://sunpladining.com/","company.link_text_c1e22e58":"https://sunpla-style.co.jp/","company.link_text_6f40e065":"https://www.dotfound.co.jp/","company.text_778b471":"会社概要 | STAGE PARTNERS","company.text_5f60ceab":"STAGE PARTNERSの会社概要ページです。"}}'::jsonb);
