insert into public.cms_documents(module,slug,draft) values('pages','privacy','{"title":"プライバシーポリシー","fields":{"privacy.text_8c2e5d33":"プライバシーポリシー | STAGE PARTNERS","privacy.text_efbceb4a":"株式会社STAGE PARTNERSの個人情報の取扱いについて。","privacy.text_89685dc6":"プライバシーポリシー","privacy.text_425f89c5":"株式会社STAGE PARTNERS（以下「当社」といいます）は、お客様の個人情報を適切に取り扱うことが社会的責務であると認識し、以下のとおりプライバシーポリシー（以下「本ポリシー」といいます）を定めます。","privacy.text_f0e09fe7":"2026年8月25日","privacy.text_849126f":"第1条（個人情報）","privacy.text_4105e239":"「個人情報」とは、個人情報保護法にいう「個人情報」を指し、生存する個人に関する情報であって、氏名、生年月日、住所、電話番号、連絡先その他の記述等により特定の個人を識別できる情報、および容貌、指紋、声紋にかかるデータ、健康保険証の保険者番号など、個人識別符号が含まれる情報を指します。","privacy.text_3ad795fe":"第2条（取得する情報と方法）","privacy.text_8696f5f6":"当社は、お問い合わせフォームおよびお電話でのお問い合わせの際に、氏名、会社名（法人のお客様の場合）、電話番号、メールアドレス、ご住所、お問い合わせ内容等の個人情報をお客様よりご提供いただきます。","privacy.text_32d8b6be":"不動産の仲介・買取・管理、または建築・リフォームのご依頼にあたっては、契約手続きに必要な範囲で、上記に加えて物件情報等をお伺いする場合があります。","privacy.text_4eecabd1":"第3条（利用目的）","privacy.text_a222d8ec":"当社は、取得した個人情報を、以下の目的の範囲内で利用します。","privacy.text_eadf4382":"お問い合わせ・ご相談への対応、および必要事項のご連絡のため","privacy.text_bbd529fe":"不動産の仲介・管理・買取再販、建築・リフォームに関するサービスの提供、見積り作成、契約手続きのため","privacy.text_7ec6dcc1":"工事・取引に関する重要事項のご連絡、アフターサービスの提供のため","privacy.text_7a15095f":"採用選考に関するご連絡のため（採用応募の場合）","privacy.text_ecc98470":"上記利用目的に付随する目的のため","privacy.text_df51b0ca":"第4条（第三者提供）","privacy.text_43e43d0":"当社は、次に掲げる場合を除き、あらかじめお客様の同意を得ることなく、第三者に個人情報を提供しません。","privacy.text_a17c3751":"法令に基づく場合","privacy.text_39eeece1":"人の生命、身体または財産の保護のために必要がある場合であって、本人の同意を得ることが困難であるとき","privacy.text_c0c7f702":"取引の性質上、提携する金融機関・登記関係機関・保険会社等へ、契約手続きに必要な範囲で提供する場合","privacy.text_f55404be":"なお、当社はグループ会社（","privacy.text_ce2d4a1a":"会社概要ページ","privacy.text_4c44faff":"に掲載）と情報を共有する場合がありますが、その場合も本ポリシーに定める利用目的の範囲内で取り扱います。","privacy.text_2dcb02d5":"第5条（個人情報取扱いの委託）","privacy.text_a8ee8de9":"当社は、利用目的の達成に必要な範囲内において、個人情報の取扱いの全部または一部を委託する場合があります。この場合、委託先に対する必要かつ適切な監督を行います。","privacy.text_8959beb9":"第6条（Cookie等の利用）","privacy.text_af6ff189":"本サイトは、2026年8月時点においてアクセス解析ツールおよびCookieを利用した個人情報の取得は行っておりません。今後、サービス向上のためこれらを導入する場合は、本ポリシーを改定のうえ、その利用目的を明示します。","privacy.text_5d16781a":"第7条（安全管理措置）","privacy.text_6f771d63":"当社は、個人情報の漏えい、滅失またはき損の防止その他の個人情報の安全管理のために必要かつ適切な措置を講じます。","privacy.text_94cb4f74":"第8条（個人情報の開示・訂正・利用停止等）","privacy.text_3b54a52f":"当社は、お客様ご本人から個人情報の開示、訂正、追加、削除、利用停止を求められた場合には、ご本人であることを確認のうえ、法令に従い遅滞なく対応します。お手続きの詳細は、下記お問い合わせ窓口までご連絡ください。","privacy.text_215e9da3":"第9条（本ポリシーの変更）","privacy.text_e6d79729":"本ポリシーの内容は、法令その他本ポリシーに別段の定めのある事項を除いて、お客様に通知することなく変更することができるものとします。変更後の内容は、本サイトに掲載した時点から効力を生じるものとします。","privacy.text_9a779f43":"第10条（お問い合わせ窓口）","privacy.text_34a3e7":"本ポリシーに関するお問い合わせは、下記までご連絡ください。","privacy.text_136438f0":"お問い合わせフォーム：","privacy.text_35d80336":"お問い合わせページ"}}'::jsonb);
