insert into public.cms_documents(module,slug,draft) values('pages','site-policy','{"title":"サイトポリシー","fields":{"site-policy.text_9d314779":"サイトポリシー | STAGE PARTNERS","site-policy.text_4ef98e50":"株式会社STAGE PARTNERSが運営する本サイトのご利用にあたっての注意事項です。","site-policy.text_a0fac228":"サイトポリシー","site-policy.text_c02d9817":"本サイト（www.stagepartners.co.jp、以下「本サイト」といいます）は、株式会社STAGE PARTNERS（以下「当社」といいます）が運営しています。本サイトのご利用にあたっては、以下の内容をご確認ください。","site-policy.text_f0e09fe7":"2026年8月25日","site-policy.text_ed13a5f4":"著作権について","site-policy.text_22903841":"本サイトに掲載されている文章、画像、写真、ロゴ、その他すべてのコンテンツの著作権は、当社または正当な権利を有する第三者に帰属します。法令で認められる場合を除き、事前の許諾なく複製、転載、改変、二次利用することはできません。","site-policy.text_e8f8e7c8":"施工実績の掲載について","site-policy.text_c9b42e52":"本サイトに掲載する施工実績の一部は、グループ会社が施工したものを含みます。掲載にあたっては、施工主体を含めた表記の正確性に努めています。","site-policy.text_62031e66":"リンクについて","site-policy.text_cd64388a":"本サイトへのリンクは、原則として自由に設定いただけます。ただし、当社または本サイトの信用を損なう可能性のある形での設定はご遠慮ください。また、本サイトから他社サイトへのリンクは、リンク先の内容について当社が保証するものではありません。","site-policy.text_36a0c950":"免責事項","site-policy.text_f9b4f9d9":"当社は、本サイトに掲載する情報の正確性・最新性の維持に努めていますが、その内容を保証するものではありません。本サイトの情報を利用したことにより生じたいかなる損害についても、当社は責任を負わないものとします。","site-policy.text_44ca8029":"本サイトは、予告なく内容の変更、掲載の中止、公開の停止を行うことがあります。","site-policy.text_c3164f6c":"推奨環境","site-policy.text_2357e388":"本サイトは、最新版のGoogle Chrome、Safari、Microsoft Edge等の主要なブラウザでの閲覧を想定して制作しています。ブラウザの設定や機種によっては、正しく表示されない場合があります。","site-policy.text_2a069080":"アクセス解析について","site-policy.text_cb6d693e":"本サイトは、2026年8月時点においてアクセス解析ツールを利用していません。導入する場合は、","site-policy.text_89685dc6":"プライバシーポリシー","site-policy.text_a749f35d":"にあわせて本ページを改定します。","site-policy.text_aa892fb9":"準拠法・管轄裁判所","site-policy.text_b32240cf":"本ポリシーの解釈にあたっては、日本法を準拠法とします。本サイトに関して当社とお客様との間で紛争が生じた場合には、当社本店所在地を管轄する裁判所を第一審の専属的合意管轄裁判所とします。"}}'::jsonb);
