insert into public.cms_documents(module,slug,draft) values('pages','tokushoho','{"title":"特定商取引法に基づく表記","fields":{"tokushoho.text_54073f3e":"特定商取引法に基づく表記 | STAGE PARTNERS","tokushoho.text_d34e579b":"株式会社STAGE PARTNERSの特定商取引法に基づく表記です。","tokushoho.text_8d4b30b5":"特定商取引法に基づく表記","tokushoho.text_26971c89":"本サイトは、不動産の仲介・管理・買取再販、建築・リフォームに関するご相談・お問い合わせの受付を目的としており、サイト上での商品の通信販売やオンライン決済は行っておりません。特定商取引法（第11条）に基づき、以下のとおり表示します。","tokushoho.text_f0e09fe7":"2026年8月25日","tokushoho.text_dc2ba448":"事業者・所在地・連絡先","tokushoho.text_8a948468":"販売業者","tokushoho.text_c62aae6b":"運営統括責任者","tokushoho.text_372b8b13":"代表取締役","tokushoho.text_922b61e0":"※個人名の表記は、","tokushoho.text_ce2d4a1a":"会社概要ページ","tokushoho.text_c9976df3":"と同じ方針により省略しています。お問い合わせいただいた際に担当者よりご案内します。","tokushoho.text_ece821ff":"所在地","tokushoho.text_bb393442":"電話番号","tokushoho.text_1f2ef4c3":"受付時間　","tokushoho.text_6eda855c":"お問い合わせ","tokushoho.text_bf0ec64a":"お問い合わせフォーム","tokushoho.text_910169e3":"よりご連絡ください。","tokushoho.text_6a49f7db":"事業内容","tokushoho.text_8ed28038":"不動産ソリューション（仲介・管理・買取再販）、建築ソリューション（新規出店・リノベーション・営繕）。詳細は","tokushoho.text_28f6c7df":"事業内容ページ","tokushoho.text_e2ff9308":"をご覧ください。","tokushoho.text_23f137d":"料金・お見積りについて","tokushoho.text_2eec4d57":"仲介手数料、工事費用等は、物件の状況・工事内容により個別に異なります。正式なご依頼の前に、必ず個別のお見積りをご提示し、ご了承をいただいたうえで契約手続きに進みます。サイト上での価格提示や、その場でのオンライン決済は行っておりません。","tokushoho.text_9ad02749":"契約の成立・引渡時期","tokushoho.text_b45a0e6a":"不動産の仲介・売買、および工事の請負契約は、それぞれの取引に定める重要事項説明・契約書の締結をもって成立します。引渡し・着工・完工の時期は、個別の契約書に定めるとおりとします。","tokushoho.text_9bd34118":"お支払い方法・キャンセルについて","tokushoho.text_de46b6df":"お支払い方法・お支払い時期は、契約締結時に個別にご案内します。契約後のキャンセル・変更については、宅地建物取引業法・建設業法等の関係法令、および個別の契約書に定める条件に従います。","tokushoho.text_b935f4c4":"許認可","tokushoho.text_7c0f463c":"宅地建物取引業免許、一般建設業登録、一級建築士事務所登録。登録番号を含む詳細は","tokushoho.text_7e666eeb":"に掲載しています。"}}'::jsonb);
